import os
import re
from datetime import datetime
from pathlib import Path

import pytesseract
from openpyxl import Workbook
from PIL import Image

IMG_DIR = Path("/app/workspace/dataset/img")
OUT_XLSX = Path("/app/workspace/stat_ocr.xlsx")

MONTH_MAP = {
    "jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
    "jul": 7, "aug": 8, "sep": 9, "sept": 9, "oct": 10, "nov": 11, "dec": 12,
    "january": 1, "february": 2, "march": 3, "april": 4, "june": 6,
    "july": 7, "august": 8, "september": 9, "october": 10, "november": 11,
    "december": 12,
}

EXCLUSION_KEYWORDS = [
    "SUBTOTAL",
    "SUB TOTAL",
    "SUB-TOTAL",
    "TAX",
    "GST",
    "SST",
    "DISCOUNT",
    "CHANGE",
    "CASH TENDERED",
]

# Priority levels: lower number = higher priority
PRIORITY_KEYWORDS = [
    (1, ["GRAND TOTAL"]),
    (2, ["TOTAL RM", "TOTAL: RM"]),
    (3, ["TOTAL AMOUNT"]),
    (4, ["TOTAL DUE", "AMOUNT DUE", "BALANCE DUE", "NETT TOTAL", "NET TOTAL",
         "TOTAL", "AMOUNT"]),
]

AMOUNT_RE = re.compile(r"(\d{1,3}(?:,\d{3})*\.\d{2}|\d+\.\d{2})")


def extract_date(text: str):
    """Return date in ISO format YYYY-MM-DD or None."""
    # Pattern 1: DD/MM/YYYY, DD-MM-YYYY, DD.MM.YYYY
    for m in re.finditer(
        r"(?<!\d)(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{2,4})(?!\d)", text
    ):
        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if y < 100:
            y += 2000
        if 1 <= d <= 31 and 1 <= mo <= 12 and 2000 <= y <= 2099:
            try:
                return datetime(y, mo, d).strftime("%Y-%m-%d")
            except ValueError:
                continue

    # Pattern 2: DD MMM YYYY  or  DD-MMM-YYYY
    for m in re.finditer(
        r"(?<!\d)(\d{1,2})[\s\-]+([A-Za-z]{3,9})[\s\-]+(\d{2,4})(?!\d)", text
    ):
        d = int(m.group(1))
        mo_str = m.group(2).lower()
        if mo_str not in MONTH_MAP:
            continue
        mo = MONTH_MAP[mo_str]
        y = int(m.group(3))
        if y < 100:
            y += 2000
        if 1 <= d <= 31 and 2000 <= y <= 2099:
            try:
                return datetime(y, mo, d).strftime("%Y-%m-%d")
            except ValueError:
                continue

    # Pattern 3: YYYY-MM-DD
    for m in re.finditer(
        r"(?<!\d)(\d{4})[/\-.](\d{1,2})[/\-.](\d{1,2})(?!\d)", text
    ):
        y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if 1 <= d <= 31 and 1 <= mo <= 12 and 2000 <= y <= 2099:
            try:
                return datetime(y, mo, d).strftime("%Y-%m-%d")
            except ValueError:
                continue

    return None


def has_exclusion(line_upper: str) -> bool:
    return any(kw in line_upper for kw in EXCLUSION_KEYWORDS)


def match_priority(line_upper: str):
    """Return (priority, keyword) if line matches a priority keyword, else None."""
    for prio, kws in PRIORITY_KEYWORDS:
        for kw in kws:
            if kw in line_upper:
                return prio, kw
    return None


def parse_amount(number_str: str) -> str:
    """Parse an amount string like '1,234.56' or '80.91' and return normalized."""
    return number_str.replace(",", "")


def extract_total(text: str):
    """Return total amount as a string with 2 decimal places, or None."""
    lines = text.splitlines()
    candidates = []  # list of (priority, value_string)

    for i, line in enumerate(lines):
        up = line.upper()
        if has_exclusion(up):
            continue
        prio_match = match_priority(up)
        if prio_match is None:
            continue
        prio, kw = prio_match

        amounts = AMOUNT_RE.findall(line)
        if amounts:
            # Pick the last amount on the line
            val = parse_amount(amounts[-1])
            candidates.append((prio, i, val))
            continue

        # Fallback: look at next line (and possibly one after)
        for j in range(i + 1, min(i + 3, len(lines))):
            next_line = lines[j]
            next_up = next_line.upper()
            if has_exclusion(next_up):
                break
            amounts = AMOUNT_RE.findall(next_line)
            if amounts:
                val = parse_amount(amounts[-1])
                candidates.append((prio, i, val))
                break

    if not candidates:
        return None

    # Sort by priority (ascending) then by line index (ascending preferred? or descending?)
    # Prefer highest priority, then the last matching candidate at that priority
    candidates.sort(key=lambda x: (x[0], -x[1]))
    _, _, val = candidates[0]
    try:
        f = float(val)
        return f"{f:.2f}"
    except ValueError:
        return None


def process_image(path: Path):
    img = Image.open(path)
    text = pytesseract.image_to_string(img)
    date = extract_date(text)
    total = extract_total(text)
    return date, total, text


def main():
    rows = []
    for fname in sorted(os.listdir(IMG_DIR)):
        if not fname.lower().endswith((".jpg", ".jpeg", ".png")):
            continue
        path = IMG_DIR / fname
        date, total, _ = process_image(path)
        rows.append((fname, date, total))
        print(f"{fname}: date={date}, total={total}")

    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for r in rows:
        ws.append(list(r))
    wb.save(OUT_XLSX)
    print(f"Saved {OUT_XLSX}")


if __name__ == "__main__":
    main()
