import os
import re
from datetime import datetime
from pathlib import Path

import pytesseract
from openpyxl import Workbook
from PIL import Image

IMG_DIR = Path("/app/workspace/dataset/img")
OUT_XLSX = Path("/app/workspace/stat_ocr.xlsx")

MONTH_MAP = {
    "jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
    "jul": 7, "aug": 8, "sep": 9, "sept": 9, "oct": 10, "nov": 11, "dec": 12,
    "january": 1, "february": 2, "march": 3, "april": 4, "june": 6,
    "july": 7, "august": 8, "september": 9, "october": 10, "november": 11,
    "december": 12,
}

# Hard exclusion keywords - lines containing these are skipped
HARD_EXCLUSION = [
    "SUBTOTAL", "SUB TOTAL", "SUB-TOTAL",
    "DISCOUNT",
    "CHANGE",
    "CASH TENDERED",
]

# Priority (lower = higher priority)
# For each priority level, list of keyword patterns.
PRIORITY_KEYWORDS = [
    (1, ["GRAND TOTAL"]),
    (2, ["TOTAL RM", "TOTAL: RM"]),
    (3, ["TOTAL AMOUNT"]),
    (4, ["TOTAL DUE", "AMOUNT DUE", "BALANCE DUE", "NETT TOTAL", "NET TOTAL",
         "TOTAL", "AMOUNT"]),
]

AMOUNT_RE = re.compile(r"(\d{1,3}(?:,\d{3})+\.\d{2}|\d+\.\d{2})")


def extract_date(text: str):
    """Return date in ISO format YYYY-MM-DD or None."""
    lines = text.splitlines()
    # Prefer lines containing "Date"
    candidate_lines = [(1 if "date" in l.lower() else 2, i, l) for i, l in enumerate(lines)]
    candidate_lines.sort(key=lambda t: (t[0], t[1]))

    def _parse_line(line: str):
        # DD/MM/YYYY etc
        for m in re.finditer(
            r"(?<!\d)(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{2,4})(?!\d)", line
        ):
            d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
            if y < 100:
                y += 2000
            if 1 <= d <= 31 and 1 <= mo <= 12 and 2000 <= y <= 2099:
                try:
                    return datetime(y, mo, d).strftime("%Y-%m-%d")
                except ValueError:
                    continue
        # DD MMM YYYY
        for m in re.finditer(
            r"(?<!\w)(\d{1,2})[\s\-]+([A-Za-z]{3,9})[\s\-]+(\d{2,4})(?!\d)", line
        ):
            d = int(m.group(1))
            mo_str = m.group(2).lower()
            if mo_str not in MONTH_MAP:
                continue
            mo = MONTH_MAP[mo_str]
            y = int(m.group(3))
            if y < 100:
                y += 2000
            if 1 <= d <= 31 and 2000 <= y <= 2099:
                try:
                    return datetime(y, mo, d).strftime("%Y-%m-%d")
                except ValueError:
                    continue
        return None

    for _, _, line in candidate_lines:
        parsed = _parse_line(line)
        if parsed:
            return parsed
    return None


def is_hard_excluded(line_upper: str) -> bool:
    return any(kw in line_upper for kw in HARD_EXCLUSION)


def is_gst_summary_line(line_upper: str) -> bool:
    # Specific GST section indicator
    return "GST SUMMARY" in line_upper or "GST  SUMMARY" in line_upper


def is_line_about_tax(line_upper: str) -> bool:
    """Return True if line is primarily about tax/GST amount (not modifier)."""
    # Lines like "Total GST", "GST Payable", "GST 6%", "Tax Amount"
    # Pattern: GST/TAX appears as subject
    # Exclude if GST/TAX appears in parentheses or after "inclusive/incl/including"

    # Check for "inclusive" patterns - if present, GST is a modifier, NOT a tax amount line
    inclusive_patterns = [
        r"\bINCL(USIVE|UDING)?\b",
        r"\(GST[\s)]*",   # GST in parens
        r"\(.*GST.*\)",
    ]
    for p in inclusive_patterns:
        if re.search(p, line_upper):
            # If GST is modifier (in parens or inclusive context), not a tax amount line
            return False

    # Primary tax/GST patterns
    # "Total GST" or "GST Payable" or "GST 6%" or "Tax Amount" etc
    tax_patterns = [
        r"\bTOTAL\s+GST\b",
        r"\bTOTAL\s+TAX\b",
        r"\bTOTAL\s+SST\b",
        r"\bGST\s+PAYABLE\b",
        r"\bGST\s+AMOUNT\b",
        r"\bGST\s+\d",   # GST 6% or similar
        r"\bTAX\s+AMOUNT\b",
        r"^\s*GST\b",
        r"^\s*TAX\b",
        r"^\s*SST\b",
        r"\bS:GST",
        r"\bS\s*GST\b",
    ]
    for p in tax_patterns:
        if re.search(p, line_upper):
            return True
    return False


def match_priority(line_upper: str):
    for prio, kws in PRIORITY_KEYWORDS:
        for kw in kws:
            if kw in line_upper:
                return prio, kw
    return None


def parse_amount(number_str: str) -> str:
    return number_str.replace(",", "")


def extract_total(text: str):
    """Return total amount as string with 2 decimal places, or None."""
    lines = text.splitlines()

    # Determine where "GST Summary" section starts to filter it out
    gst_summary_start = None
    for i, line in enumerate(lines):
        if is_gst_summary_line(line.upper()):
            gst_summary_start = i
            break

    candidates = []  # (priority, line_index, value_str)

    for i, line in enumerate(lines):
        # Skip lines in GST summary section
        if gst_summary_start is not None and i >= gst_summary_start:
            break

        up = line.upper()
        if is_hard_excluded(up):
            continue
        if is_line_about_tax(up):
            continue

        prio_match = match_priority(up)
        if prio_match is None:
            continue
        prio, kw = prio_match

        # Try to extract amount on this line
        amounts = AMOUNT_RE.findall(line)
        if amounts:
            val = parse_amount(amounts[-1])
            candidates.append((prio, i, val))
            continue

        # Fallback: look at next lines
        for j in range(i + 1, min(i + 3, len(lines))):
            next_line = lines[j]
            next_up = next_line.upper()
            if gst_summary_start is not None and j >= gst_summary_start:
                break
            if is_hard_excluded(next_up) or is_line_about_tax(next_up):
                break
            amounts = AMOUNT_RE.findall(next_line)
            if amounts:
                val = parse_amount(amounts[-1])
                candidates.append((prio, i, val))
                break

    if not candidates:
        return None

    # Sort by priority (ascending), prefer last match within same priority
    # Rationale: usually the final total appears later in the receipt
    candidates.sort(key=lambda x: (x[0], -x[1]))
    _, _, val = candidates[0]
    try:
        f = float(val)
        return f"{f:.2f}"
    except ValueError:
        return None


def process_image(path: Path):
    img = Image.open(path)
    text = pytesseract.image_to_string(img, config="--psm 6")
    date = extract_date(text)
    total = extract_total(text)
    return date, total, text


def main():
    rows = []
    for fname in sorted(os.listdir(IMG_DIR)):
        if not fname.lower().endswith((".jpg", ".jpeg", ".png")):
            continue
        path = IMG_DIR / fname
        date, total, _ = process_image(path)
        rows.append((fname, date, total))
        print(f"{fname}: date={date}, total={total}")

    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for r in rows:
        ws.append(list(r))
    wb.save(OUT_XLSX)
    print(f"Saved {OUT_XLSX}")


if __name__ == "__main__":
    main()
"}

